   405  sread(int fd, void *buf, size_t n, int canbepipe __attribute__((__unused__)))
   406  {
   407          ssize_t rv;
   408  #ifdef FIONREAD
   409          int t = 0;
   410  #endif
   411          size_t rn = n;
   412
   413          if (fd == STDIN_FILENO)
   414                  goto nocheck;
   415
   416  #ifdef FIONREAD
   417          if (canbepipe && (ioctl(fd, FIONREAD, &t) == -1 || t == 0)) {
   418  #ifdef FD_ZERO
   419                  ssize_t cnt;
   420                  for (cnt = 0;; cnt++) {
   421                          fd_set check;
   422                          struct timeval tout = {0, 100 * 1000};
   423                          int selrv;
   424
   425                          FD_ZERO(&check);
   426                          FD_SET(fd, &check);
   427
   428                          /*
   429                           * Avoid soft deadlock: do not read if there
   430                           * is nothing to read from sockets and pipes.
   431                           */
   432                          selrv = select(fd + 1, &check, NULL, NULL, &tout);
   433                          if (selrv == -1) {
   434                                  if (errno == EINTR || errno == EAGAIN)
   435                                          continue;
   436                          } else if (selrv == 0 && cnt >= 5) {
   437                                  return 0;
   438                          } else
   439                                  break;
   440                  }
   441  #endif
   442                  (void)ioctl(fd, FIONREAD, &t);
   443          }
   444
   445          if (t > 0 && CAST(size_t, t) < n) {
   446                  n = t;
   447                  rn = n;
   448          }
   449  #endif
