   451  nocheck:
   452          do
   453                  switch ((rv = read(fd, buf, n))) {
   454                  case -1:
   455                          if (errno == EINTR)
   456                                  continue;
   457                          return -1;
   458                  case 0:
   459                          return rn - n;
   460                  default:
   461                          n -= rv;
   462                          buf = CAST(char *, CCAST(void *, buf)) + rv;
   463                          break;
   464                  }
   465          while (n > 0);
   466          return rn;
   467  }
